  "android/app/src/main/res/values/strings.xml": "<resources>\n    <string name=\"app_name\">NS Guruji</string>\n    <string name=\"tagline\">सरकारी नौकरी, योजना एवं ताजा अपडेट</string>\n    \n    <!-- Navigation -->\n    <string name=\"nav_home\">होम</string>\n    <string name=\"nav_categories\">श्रेणियां</string>\n    <string name=\"nav_search\">खोजें</string>\n    <string name=\"nav_saved\">सेव किए गए</string>\n    \n    <!-- Drawer & Menu -->\n    <string name=\"menu_share\">ऐप शेयर करें</string>\n    <string name=\"menu_rate\">रेट करें</string>\n    <string name=\"menu_privacy\">गोपनीयता नीति</string>\n    <string name=\"menu_about\">हमारे बारे में</string>\n    <string name=\"menu_website\">वेबसाइट खोलें</string>\n    \n    <!-- Actions -->\n    <string name=\"retry\">पुनः प्रयास करें</string>\n    <string name=\"pull_to_refresh\">ताज़ा करने के लिए नीचे खींचें</string>\n    <string name=\"no_articles_found\">कोई लेख नहीं मिला</string>\n    <string name=\"search_placeholder\">नौकरी, प्रवेश पत्र या योजना खोजें...</string>\n    <string name=\"recent_searches\">हाल ही में खोजे गए</string>\n    <string name=\"clear_all\">सभी हटाएं</string>\n    <string name=\"share_article\">शेयर करें</string>\n    <string name=\"bookmark_added\">लेख सेव किया गया</string>\n    <string name=\"bookmark_removed\">लेख सेव सूची से हटाया गया</string>\n    <string name=\"read_more\">पूरी जानकारी पढ़ें</string>\n    <string name=\"published_on\">प्रकाशित:</string>\n    <string name=\"updated_on\">अपडेट:</string>\n    <string name=\"related_articles\">संबंधित लेख</string>\n    \n    <!-- Error states -->\n    <string name=\"error_no_internet\">इंटरनेट कनेक्शन नहीं है। कृपया अपना नेटवर्क जांचें।</string>\n    <string name=\"error_api_failed\">सर्वर से जुड़ने में समस्या हुई। कृपया पुनः प्रयास करें।</string>\n    <string name=\"error_empty_saved\">आपने अभी तक कोई लेख सेव नहीं किया है।</string>\n</resources>\n",
